#!/bin/bash
set -e

# Path to Android NDK
export NDK=/Users/anathan/Documents/android-ndk-r28c
export TOOLCHAIN=$NDK/toolchains/llvm/prebuilt/darwin-x86_64
export SYSROOT=$TOOLCHAIN/sysroot
export API=23
export PREFIX=android

# OpenH264 Android install root generated by build_openh264_android_v2.sh
export OPENH264_ROOT=/Users/anathan/Desktop/ffmpeg_build/openh264-2.6.0/android

# FFmpeg 6.0 requires pkg-config when enabling libopenh264.
# This project only needs OpenH264, so use a tiny local compatibility script
# instead of requiring Homebrew/pkg-config to be installed on macOS.
PKG_CONFIG_WRAPPER="$PWD/.openh264-pkg-config.sh"

cleanup() {
  rm -f "$PKG_CONFIG_WRAPPER"
}
trap cleanup EXIT

create_openh264_pkg_config_wrapper() {
  cat > "$PKG_CONFIG_WRAPPER" <<'PKGEOF'
#!/bin/sh

# FFmpeg configure first checks whether pkg-config itself is available.
if [ "$1" = "--version" ]; then
  echo "0.29.2"
  exit 0
fi

if [ -z "$OPENH264_PREFIX" ] || [ -z "$OPENH264_INCLUDE_DIR" ]; then
  echo "ERROR: OPENH264_PREFIX/OPENH264_INCLUDE_DIR is not set" >&2
  exit 1
fi

MODE=""
for arg in "$@"; do
  case "$arg" in
    --exists)
      MODE="exists"
      ;;
    --cflags|--cflags-only-I)
      MODE="cflags"
      ;;
    --libs)
      MODE="libs"
      ;;
    --variable=includedir)
      MODE="includedir"
      ;;
    --modversion)
      MODE="modversion"
      ;;
    --print-errors|--static)
      ;;
  esac
done

case "$MODE" in
  exists)
    [ -f "$OPENH264_INCLUDE_DIR/wels/codec_api.h" ] && \
    [ -f "$OPENH264_PREFIX/lib/libopenh264.a" ]
    ;;
  cflags)
    echo "-I$OPENH264_INCLUDE_DIR"
    ;;
  libs)
    # FFmpeg configure only needs to verify that OpenH264 is usable.
    # Use the shared library for this temporary link test so the C compiler
    # does not have to resolve OpenH264's C++ static-runtime dependencies here.
    # The final libavkit.so is still linked against libopenh264.a by
    # merge_static_to_shared.sh, so there is NO runtime libopenh264.so dependency.
    echo "-L$OPENH264_PREFIX/lib -lopenh264"
    ;;
  includedir)
    echo "$OPENH264_INCLUDE_DIR"
    ;;
  modversion)
    echo "2.6.0"
    ;;
  *)
    echo "Unsupported pkg-config arguments: $*" >&2
    exit 1
    ;;
esac
PKGEOF

  chmod +x "$PKG_CONFIG_WRAPPER"
}

# Compiler prefix for different ABIs
export CC_COMPILE_PREFIX_ARMV7=armv7a-linux-androideabi
export CC_COMPILE_PREFIX_ARM64=aarch64-linux-android
export CC_COMPILE_PREFIX_X86_64=x86_64-linux-android

# FFmpeg common configure options
COMMON_OPTIONS="\
  --prefix=$PREFIX \
  --target-os=android \
  --enable-cross-compile \
  --enable-static \
  --disable-shared \
  --disable-programs \
  --disable-ffmpeg \
  --disable-ffplay \
  --disable-ffprobe \
  --disable-doc \
  --disable-debug \
  --disable-symver \
  --disable-postproc \
  --disable-avdevice \
  --disable-iconv \
  --disable-vulkan \
  --enable-pic \
  --enable-jni \
  --enable-asm \
  --enable-neon \
  --enable-stripping \
  --enable-mediacodec \
  --enable-network \
  --disable-everything \
  \
  --enable-libopenh264 \
  \
  --enable-decoder=h264 \
  --enable-decoder=hevc \
  --enable-decoder=aac \
  --enable-decoder=opus \
  --enable-decoder=h264_mediacodec \
  --enable-decoder=hevc_mediacodec \
  --enable-decoder=mjpeg \
  \
  --enable-encoder=aac \
  --enable-encoder=h264_mediacodec \
  --enable-encoder=hevc_mediacodec \
  --enable-encoder=mjpeg \
  --enable-encoder=libopenh264 \
  \
  --enable-parser=h264 \
  --enable-parser=hevc \
  --enable-parser=aac \
  --enable-parser=opus \
  --enable-parser=mjpeg \
  \
  --enable-muxer=mp4 \
  --enable-muxer=adts \
  --enable-muxer=flv \
  --enable-muxer=rtsp \
  --enable-muxer=sdp \
  --enable-muxer=image2 \
  \
  --enable-demuxer=mov \
  --enable-demuxer=aac \
  --enable-demuxer=flv \
  --enable-demuxer=rtsp \
  --enable-demuxer=sdp \
  --enable-demuxer=image2 \
  \
  --enable-protocol=file \
  --enable-protocol=pipe \
  --enable-protocol=rtmp \
  --enable-protocol=tcp \
  --enable-protocol=udp \
  --enable-protocol=http \
  --enable-protocol=rtp \
  \
  --enable-bsf=aac_adtstoasc \
  --enable-bsf=h264_mp4toannexb \
  --enable-bsf=hevc_mp4toannexb \
  \
  --enable-avcodec \
  --enable-avformat \
  --enable-avutil \
  --enable-swresample \
  --enable-swscale"

# Function to build FFmpeg for a specific ABI
function build_ffmpeg_for_abi() {
  ABI=$1

  export OPENH264_PREFIX="$OPENH264_ROOT/$ABI"
  export OPENH264_INCLUDE_DIR="$OPENH264_PREFIX/include"

  # Compatibility fallback in case the headers were installed directly under
  # the ABI directory instead of ABI/include.
  if [ ! -f "$OPENH264_INCLUDE_DIR/wels/codec_api.h" ] && \
     [ -f "$OPENH264_PREFIX/wels/codec_api.h" ]; then
    export OPENH264_INCLUDE_DIR="$OPENH264_PREFIX"
  fi

  if [ ! -f "$OPENH264_INCLUDE_DIR/wels/codec_api.h" ]; then
    echo "ERROR: Cannot find OpenH264 header for ABI $ABI"
    echo "Expected: $OPENH264_PREFIX/include/wels/codec_api.h"
    exit 1
  fi

  if [ ! -f "$OPENH264_PREFIX/lib/libopenh264.a" ]; then
    echo "ERROR: Cannot find OpenH264 static library for ABI $ABI"
    echo "Expected: $OPENH264_PREFIX/lib/libopenh264.a"
    exit 1
  fi

  # The shared library is used only by FFmpeg configure for its compile/link
  # capability check. The final libavkit.so does NOT link against this .so.
  if [ ! -f "$OPENH264_PREFIX/lib/libopenh264.so" ]; then
    echo "ERROR: Cannot find OpenH264 shared library used for FFmpeg configure check: $ABI"
    echo "Expected: $OPENH264_PREFIX/lib/libopenh264.so"
    echo "Re-run build_openh264_android_v2.sh; make install should generate both .a and .so."
    exit 1
  fi

  case $ABI in
    armeabi-v7a)
      ARCH=arm
      CPU=armv7-a
      CC=$TOOLCHAIN/bin/${CC_COMPILE_PREFIX_ARMV7}${API}-clang
      CROSS_PREFIX=$TOOLCHAIN/bin/arm-linux-androideabi-
      EXTRA_CFLAGS="-march=armv7-a -mfloat-abi=softfp -mfpu=neon"
      EXTRA_LDFLAGS="-pie"
      ;;
    arm64-v8a)
      ARCH=aarch64
      CPU=armv8-a
      CC=$TOOLCHAIN/bin/${CC_COMPILE_PREFIX_ARM64}${API}-clang
      CROSS_PREFIX=$TOOLCHAIN/bin/aarch64-linux-android-
      EXTRA_CFLAGS="-fPIC"
      EXTRA_LDFLAGS="-pie" #-Wl,-z,common-page-size=16384 -Wl,-z,max-page-size=16384 -pie
      ;;
    x86_64)
      ARCH=x86_64
      CPU=x86_64
      CC=$TOOLCHAIN/bin/${CC_COMPILE_PREFIX_X86_64}${API}-clang
      CROSS_PREFIX=$TOOLCHAIN/bin/x86_64-linux-android-
      EXTRA_CFLAGS="-fPIC"
      EXTRA_LDFLAGS="-pie" #-Wl,-z,common-page-size=16384 -Wl,-z,max-page-size=16384 -pie
      ;;
    *)
      echo "Unsupported ABI: $ABI"
      exit 1
      ;;
  esac

  echo "Start building for ABI: $ABI"
  echo "OpenH264 include: $OPENH264_INCLUDE_DIR"
  echo "OpenH264 static library (final merge): $OPENH264_PREFIX/lib/libopenh264.a"
  echo "OpenH264 shared library (configure check only): $OPENH264_PREFIX/lib/libopenh264.so"

  /usr/bin/make distclean || true
  create_openh264_pkg_config_wrapper

  ./configure \
    --libdir=$PREFIX/lib/$ABI \
    --incdir=$PREFIX/include/$ABI \
    --pkgconfigdir=$PREFIX/pkgconfig/$ABI \
    --arch=$ARCH \
    --cpu=$CPU \
    --cc=$CC \
    --ar=$TOOLCHAIN/bin/llvm-ar \
    --nm=$TOOLCHAIN/bin/llvm-nm \
    --strip=$TOOLCHAIN/bin/llvm-strip \
    --ranlib=$TOOLCHAIN/bin/llvm-ranlib \
    --sysroot=$SYSROOT \
    --cross-prefix=$CROSS_PREFIX \
    --pkg-config="$PKG_CONFIG_WRAPPER" \
    --extra-cflags="$EXTRA_CFLAGS" \
    --extra-ldflags="$EXTRA_LDFLAGS" \
    $COMMON_OPTIONS

  /usr/bin/make -j$(sysctl -n hw.ncpu)
  /usr/bin/make install

  echo "Build finished for ABI: $ABI"

  ./merge_static_to_shared.sh $ABI $PREFIX $API
}

# Create the local pkg-config compatibility script once. It reads the current
# ABI paths from OPENH264_PREFIX/OPENH264_INCLUDE_DIR during configure.
create_openh264_pkg_config_wrapper

# ABIs to build
ABIS=("armeabi-v7a" "arm64-v8a")

# Build FFmpeg for each ABI
for ABI in "${ABIS[@]}"; do
  build_ffmpeg_for_abi $ABI
done

echo "All builds completed."
